#requires -Version 7.0
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$inputPath = Join-Path $root 'baseline/host/Data/test.json'
$bytes = [IO.File]::ReadAllBytes($inputPath)
$text = [Text.UTF8Encoding]::new($false).GetString($bytes)
$document = [System.Text.Json.JsonDocument]::Parse([string]$text)
$stack = [Collections.Generic.Stack[System.Text.Json.JsonElement]]::new()
$stack.Push($document.RootElement)
$counts = [ordered]@{ True=0; False=0; Null=0; AllValueNodes=0 }
while ($stack.Count -gt 0) {
    $element = $stack.Pop()
    $counts.AllValueNodes++
    switch ($element.ValueKind) {
        'True' { $counts.True++ }
        'False' { $counts.False++ }
        'Null' { $counts.Null++ }
        'Array' { foreach ($child in $element.EnumerateArray()) { $stack.Push($child) } }
        'Object' { foreach ($property in $element.EnumerateObject()) { $stack.Push($property.Value) } }
    }
}
$record = [ordered]@{
    Input='baseline/host/Data/test.json'
    Bytes=$bytes.Length
    SHA256=(Get-FileHash -LiteralPath $inputPath -Algorithm SHA256).Hash
    Parser='System.Text.Json.JsonDocument.Parse(string)'
    CountedAs='JSON value nodes including containers and scalars; property names excluded'
    True=$counts.True
    False=$counts.False
    Null=$counts.Null
    TotalWordLiteralNodes=($counts.True+$counts.False+$counts.Null)
    AllValueNodes=$counts.AllValueNodes
}
$document.Dispose()
$outputPath = Join-Path $root 'word-literal-node-counts.json'
ConvertTo-Json -InputObject $record -Depth 6 | Set-Content -LiteralPath $outputPath -Encoding utf8
Write-Output ($record | ConvertTo-Json -Compress)

